		/** Resolve the sprite symbol id for one tree row. */
		function fileIconId(name, type, isOpen) {
			if (type === "directory") return isOpen ? FILE_ICON_DIR_OPEN : FILE_ICON_DIR;
			const lower = String(name).toLowerCase();
			const bare = lower.startsWith(".") ? lower.slice(1) : lower;
			const byName = FILE_ICON_BY_NAME[bare];
			if (byName !== undefined) return byName;
			const dot = bare.lastIndexOf(".");
			if (dot > 0 && dot < bare.length - 1) {
				const byExt = FILE_ICON_BY_EXT[bare.slice(dot + 1)];
				if (byExt !== undefined) return byExt;
			}
			return FILE_ICON_FALLBACK;
		}

